#include <iostream>
#include <memory>
#include <string>
using namespace std;

class Cat {
public:
    virtual string speak() const { return "……"; }
    virtual ~Cat() = default;
};

class FishCat : public Cat {
public:
    string speak() const override { return "小鱼干喵！"; }
};

class BallCat : public Cat {
public:
    string speak() const override { return "毛线球喵！"; }
};

unique_ptr<Cat> makeCat(const string& kind) {
    if (kind == "fish") return make_unique<FishCat>();
    return make_unique<BallCat>();
}

int main() {
    auto c1 = makeCat("fish");
    auto c2 = makeCat("ball");
    auto c3 = makeCat("别的");
    cout << c1->speak() << endl;
    cout << c2->speak() << endl;
    cout << c3->speak() << endl;
    return 0;
}

#include <iostream>
#include <functional>
#include <string>
#include <vector>
using namespace std;

class DinnerBell {
public:
    void listen(function<void(const string&)> ear) { ears.push_back(ear); }
    void ring(const string& what) const {
        for (auto& ear : ears) ear(what);
    }
private:
    vector<function<void(const string&)>> ears;
};

int main() {
    DinnerBell bell;
    bell.listen([](const string& what) { cout << "咪爱听见了：" << what << endl; });
    bell.listen([](const string& what) { cout << "大肥鱼听见了：" << what << endl; });
    bell.listen([](const string& what) {
        if (what == "小鱼干") cout << "（毛线球猫听见了）" << endl;
    });
    bell.ring("小鱼干");
    bell.ring("猫粮");
    return 0;
}
